var QRCode = __toESM(require_browser());
var AssetTicketScanConverter = class {
  static empty() {
    return {
      avatarUrl: "",
      initials: "",
      personLine: "",
      roleBadgeLabel: "",
      eventLine: "",
      dateLine: ""
    };
  }
  static convert(payload, user) {
    if (!payload) {
      return this.empty();
    }
    return {
      avatarUrl: payload.holderAvatarUrl?.trim() || (user ? AppUtils.firstImageUrl(user.images) : ""),
      initials: payload.holderInitials?.trim() || user?.initials?.trim() || AppUtils.initialsFromText(payload.holderName),
      personLine: `${payload.holderName}, ${payload.holderAge} \xB7 ${payload.holderCity}`,
      roleBadgeLabel: this.contextualRoleBadge(payload.holderRole),
      eventLine: payload.eventTitle,
      dateLine: payload.eventTimeframe || payload.eventDateLabel
    };
  }
  static contextualRoleBadge(role) {
    return role.trim();
  }
  static async qrImageDataUrl(scanCode) {
    const normalizedCode = scanCode.trim();
    if (!normalizedCode) {
      return "";
    }
    return QRCode.toDataURL(normalizedCode, {
      errorCorrectionLevel: "Q",
      margin: 0,
      width: 1024
    });
  }
};

